/**
 * A compact Markdown parser for your project.
 * Save this entire block as 'marked.min.js'
 */
window.marked = {
    parse: function (md) {
        let html = md
            .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;') // Security
            .replace(/^### (.*$)/gim, '<h3>$1</h3>') // H3
            .replace(/^## (.*$)/gim, '<h2>$1</h2>')  // H2
            .replace(/^# (.*$)/gim, '<h1>$1</h1>')   // H1
            .replace(/^\> (.*$)/gim, '<blockquote>$1</blockquote>') // Quotes
            .replace(/\*\*(.*)\*\*/gim, '<strong>$1</strong>') // Bold
            .replace(/\*(.*)\*/gim, '<em>$1</em>') // Italic
            .replace(/!\[(.*?)\]\((.*?)\)/gim, "<img alt='$1' src='$2' />") // Images
            .replace(/\[(.*?)\]\((.*?)\)/gim, "<a href='$2'>$1</a>") // Links
            .replace(/\n$/gim, '<br />'); // Line breaks

        // Wrap lines in paragraphs if they aren't already tags
        return html.split('\n').map(line => {
            return line.trim().startsWith('<') ? line : `<p>${line}</p>`;
        }).join('\n');
    }
};
